var a=11;var i=[{id:`cooking-011-01`,theoryId:11,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Which senses contribute most directly to evaluating a finished dish?`,ua:`Які відчуття безпосередньо допомагають оцінити готову страву?`},explanation:{en:`Sensory quality is multidimensional: one signal cannot represent the whole dish.`,ua:`Органолептична якість багатовимірна: один показник не характеризує всю страву.`},options:[{id:`a`,text:{en:`Taste, aroma, texture, appearance, and sometimes sound`,ua:`Смак, аромат, текстура, вигляд, іноді звук`}},{id:`b`,text:{en:`Only the color of the plate`,ua:`Лише колір тарілки`}},{id:`c`,text:{en:`Only cooking time`,ua:`Лише час приготування`}},{id:`d`,text:{en:`Only the ingredient price`,ua:`Лише ціна інгредієнтів`}}],answer:{optionIds:[`a`]}},{id:`cooking-011-02`,theoryId:11,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match a sensory observation to the likely attribute.`,ua:`Поєднайте спостереження з органолептичною характеристикою.`},explanation:{en:`Separate texture, smell, and taste when diagnosing a dish.`,ua:`Під час оцінювання розрізняйте текстуру, запах і смак.`},leftItems:[{id:`l1`,text:{en:`Crunch`,ua:`Хрускіт`}},{id:`l2`,text:{en:`Citrus scent`,ua:`Цитрусовий запах`}},{id:`l3`,text:{en:`Salty perception`,ua:`Відчуття солоного`}}],rightItems:[{id:`r3`,text:{en:`Taste`,ua:`Смак`}},{id:`r2`,text:{en:`Aroma`,ua:`Аромат`}},{id:`r1`,text:{en:`Texture`,ua:`Текстура`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-011-03`,theoryId:11,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A soup tastes flat but is already salty. What is the most useful next check?`,ua:`Суп здається прісним, але він уже солоний. Що найдоцільніше перевірити?`},explanation:{en:`Flat flavor is not always a shortage of salt; small adjustments can improve balance.`,ua:`Прісність не завжди означає нестачу солі; невеликі корекції можуть урівноважити смак.`},options:[{id:`a`,text:{en:`Balance of acidity and aromatics`,ua:`Баланс кислотності й ароматичних складників`}},{id:`b`,text:{en:`Add a large pinch of salt immediately`,ua:`Одразу додати багато солі`}},{id:`c`,text:{en:`Discard the thermometer`,ua:`Викинути термометр`}},{id:`d`,text:{en:`Double the liquid without tasting`,ua:`Подвоїти рідину без дегустації`}}],answer:{optionIds:[`a`]}},{id:`cooking-011-04`,theoryId:11,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`A pleasant smell guarantees a food is safe to eat.`,ua:`Приємний запах гарантує, що продукт безпечний для споживання.`},explanation:{en:`Dangerous pathogens may be present without a detectable change in odor.`,ua:`Небезпечні патогени можуть бути присутні без відчутної зміни запаху.`},answer:{value:!1}},{id:`cooking-011-05`,theoryId:11,type:`sequence`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Order a useful sensory review of a safe finished dish.`,ua:`Розташуйте етапи органолептичного оцінювання безпечної готової страви.`},explanation:{en:`Consistent observation and small changes make evaluation repeatable.`,ua:`Послідовне спостереження й невеликі зміни роблять оцінювання відтворюваним.`},steps:[{id:`s2`,text:{en:`Taste a small appropriate portion and notice texture`,ua:`Спробувати невелику доречну порцію й оцінити текстуру`}},{id:`s4`,text:{en:`Taste again and record the result`,ua:`Повторно спробувати й зафіксувати результат`}},{id:`s1`,text:{en:`Observe appearance and aroma`,ua:`Оцінити вигляд та аромат`}},{id:`s3`,text:{en:`Describe imbalance and make a small controlled adjustment`,ua:`Назвати дисбаланс та внести невелику контрольовану корекцію`}}],answer:{order:[`s1`,`s2`,`s3`,`s4`]}}];var n={theoryId:11,exercises:i};export{n as default,i as exercises,a as theoryId};